def try_read(self, address, size):
    """Try to read memory content at specified address.

    If any location was not written before, it returns a tuple
    (False, None). Otherwise, it returns (True, memory content).

    """
    value = 0x0

    for i in range(0, size):
        addr = address + i

        if addr in self._memory:
            value |= self._read_byte(addr) << (i * 8)
        else:
            return False, None

    return True, value

def read_memory(self, address, size):
    assert size == 1

    return self._memory.get(address, None)

def read_c_string(emulator, address, max_length=1024):
    i = 0
    data = bytearray()
    while i < max_length:
        b = emulator.read_memory(address + i, 1)
        if b == 0:
            break
        data.append(b)
        i += 1
    return data.decode()

def _cast_to_bool(value):
    if type(value) is bool:
        value = Bool(str(value).lower())

    assert type(value) == Bool

    return value

def _cast_to_bitvec(value, size):
    if type(value) in (int, long):
        value = Constant(size, value)

    assert type(value) in (Constant, BitVec) and value.size == size

    return value

def concat(size, *args):
    if len(args) == 1:
        return args[0]

    return BitVec(size * len(args), "concat", *args)

def __cs_reg_idx_to_arm_op_reg(self, cs_reg_idx, cs_insn):
    name = str(cs_insn.reg_name(cs_reg_idx))
    if name in arm_alias_reg_map:
        name = arm_alias_reg_map[name]

    if name in self._arch_info.registers_size:
        size = self._arch_info.registers_size[name]
    else:
        size = self._arch_info.architecture_size

    return ArmRegisterOperand(name, size)

def __cs_shift_to_arm_op(self, cs_op, cs_insn, arm_base):
    if cs_op.shift.type == 0:
        raise Exception("Invalid shift type.")

    cs_shift_mapper = {
        ARM_SFT_ASR:     "asr",
        ARM_SFT_LSL:     "lsl",
        ARM_SFT_LSR:     "lsr",
        ARM_SFT_ROR:     "ror",
        ARM_SFT_RRX:     "rrx",
        ARM_SFT_ASR_REG: "asr",
        ARM_SFT_LSL_REG: "lsl",
        ARM_SFT_LSR_REG: "lsr",
        ARM_SFT_ROR_REG: "ror",
        ARM_SFT_RRX_REG: "rrx",
    }

    # The base register (arm_base) is not included in the shift
    # struct in Capstone, so it's provided separately.
    sh_type = cs_shift_mapper[cs_op.shift.type]

    if cs_op.shift.type <= ARM_SFT_RRX:
        amount = ArmImmediateOperand(cs_op.shift.value, self._arch_info.operand_size)

        # TODO: check if this is a valid case.
        if cs_op.shift.value == 0:
            raise Exception("Shift value is zero.")
    elif cs_op.shift.type <= ARM_SFT_RRX_REG:
        amount = self.__cs_reg_idx_to_arm_op_reg(cs_op.shift.value, cs_insn)
    else:
        raise Exception("Unknown shift type.")

    return ArmShiftedRegisterOperand(arm_base, sh_type, amount, arm_base.size)

