    bb_type = bb_get_type(bb)

    return Node(bb.address, label=bb_dump, color=self.node_color[bb_type], **self.node_format)

def address(self):
    """Get basic block start address.
    """
    if len(self._instrs) == 0:
        return None

    return self._instrs[0].address

def start_address(self):
    """Get basic block start address.
    """
    if self._instrs is []:
        return None

    return self._instrs[0].address

def end_address(self):
    """Get basic block end address.
    """
    if self._instrs is []:
        return None

    return self._instrs[-1].address + self._instrs[-1].size - 1

def size(self):
    """Get basic block size.
    """
    if self._instrs is []:
        return None

    return sum([instr.size for instr in self._instrs])

def __str__(self):
    lines = ["Basic Block @ {:#x}".format(self.address if self.address else 0)]

    asm_fmt = "{:#x}    {}"
    reil_fmt = "{:#x}:{:02d} {}"

    for asm_instr in self._instrs:
        lines += [asm_fmt.format(asm_instr.address, asm_instr)]

        for reil_instr in asm_instr.ir_instrs:
            lines += [reil_fmt.format(reil_instr.address >> 0x8, reil_instr.address & 0xff, reil_instr)]

    return "\n".join(lines)

def __eq__(self, other):
    # Assumes that you are comparing basic block from the same binary
    return self.address == other.address and self.end_address == other.end_address

def exit_basic_blocks(self):
    for bb_addr in self._exit_blocks:
        yield self._bb_by_addr[bb_addr]

def _find_basic_block(self, address):
    bb_rv = None

    for bb in self._basic_blocks:
        if bb.address <= address <= bb.end_address:
            bb_rv = bb
            break

    return bb_rv

def find_basic_block(self, start):
    bb_rv = None

    for bb in self._basic_blocks:
        if bb.address == start:
            bb_rv = bb
            break

    return bb_rv

def branches(self):
    """Get basic block branches.
    """
    branches = []

    if self._taken_branch:
        branches += [(self._taken_branch, 'taken')]

    if self._not_taken_branch:
        branches += [(self._not_taken_branch, 'not-taken')]

    if self._direct_branch:
        branches += [(self._direct_branch, 'direct')]

    return branches

def _build_graph(self):
    graph = networkx.DiGraph()

    # add nodes
    for bb_addr in self._bb_by_addr.keys():
        graph.add_node(bb_addr, address=bb_addr)

    # add edges
    for bb_src_addr in self._bb_by_addr.keys():
        for bb_dst_addr, branch_type in self._bb_by_addr[bb_src_addr].branches:
            graph.add_edge(bb_src_addr, bb_dst_addr, branch_type=branch_type)

    return graph

def analyze(self):
    # Fetch instruction from the trace.
    asm_instr, _, _, _ = self._trace.current()

    # Execute instruction.
    try:
        self._next_addr = self._emulator.execute(asm_instr)
        self._set_regs = False
    except barf.arch.emulator.Syscall:
        self._next_addr = None
        self._set_regs = True
    except barf.arch.emulator.InstructionNotImplemented as e:
        print("[-] Instruction not implemented: {:#x} {}".format(asm_instr.address, e.instruction))

        if self._options.abort:
            sys.exit(1)
        else:
            self._next_addr = asm_instr.address + asm_instr.size
            self._set_regs = True

def __getstate__(self):
    state = {
        '_instrs': self._instrs,
        '_address': self._address,
        '_taken_branch': self._taken_branch,
        '_not_taken_branch': self._not_taken_branch,
        '_direct_branch': self._direct_branch,
    }

    return state

def __init__(self, dct, **kwargs):
    super(DotDict, self).__init__(**kwargs)

    for key, value in dct.items():
        if hasattr(value, 'keys'):
            value = DotDict(value)
        self[key] = value

def _build_graph(self):
    graph = networkx.DiGraph()

    # add nodes
    for cfg in self._cfgs:
        graph.add_node(cfg.start_address, address=cfg.start_address)

    graph.add_node("unknown", address="unknown")

    # add edges
    for cfg in self._cfgs:
        edges = self._edges.get(cfg.start_address, set())

        for bb in cfg.basic_blocks:
            for instr in bb:
                if instr.mnemonic == "call":
                    if isinstance(instr.operands[0], X86ImmediateOperand):
                        target_addr = instr.operands[0].immediate

                        edges.add(target_addr)

                        graph.add_edge(cfg.start_address, target_addr, branch_type="direct")
                    else:
                        edges.add("unknown")

                        graph.add_edge(cfg.start_address, "unknown", branch_type="indirect")

        self._edges[cfg.start_address] = edges

    return graph

def find_function_by_name(self, name):
    """Return the cfg of the requested function by name.
    """
    cfg_rv = None
    for cfg in self._cfgs:
        if cfg.name == name:
            cfg_rv = cfg
            break
    return cfg_rv

def find_function_by_address(self, address):
    """Return the cfg of the requested function by address.
    """
    cfg_rv = None
    for cfg in self._cfgs:
        if cfg.start_address == address:
            cfg_rv = cfg
            break
    return cfg_rv

def save(self, cf, filename, format='dot'):
