def save_cfg_graph(cfg, output_dir, show_reil, fmt, immediate_format):
    options = {
        "immediate_format": immediate_format
    }

    cfg.save(output_dir + os.path.sep + cfg.name, print_ir=show_reil, format=fmt, options=options)

def save_cfg_text(cfg, output_dir, show_reil, brief):
    fn_name = cfg.name
    fn_start = cfg.start_address
    fn_end = cfg.end_address

    with open(output_dir + os.path.sep + fn_name + ".txt", "w") as f:
        print("Function : {} [{:#x} - {:#x}]".format(fn_name, fn_start, fn_end), file=f)

        for bb in cfg.basic_blocks:
            branches = ", ".join(sorted(["{:#x}".format(a) for a, _ in bb.branches]))

            print("[basic block] {:#x}:{:#x} -> {}".format(bb.start_address, bb.end_address + 1, branches), file=f)

            if not brief:
                for instr in bb:
                    print("  {:#x}    {}".format(instr.address, instr), file=f)

                    if show_reil:
                        for reil_instr in instr.ir_instrs:
                            print("  {:#x}:{:02x}   {}".format(reil_instr.address >> 0x8, reil_instr.address & 0xFF, reil_instr), file=f)

def save_cfgs(cfgs, output_dir, output_format, show_reil, brief, immediate_format):
    for cfg in cfgs:
        if len(cfg.basic_blocks) == 0:
            print("[*] Ignoring empty CFG: {}".format(cfg.name))
            continue

        if output_format in ["pdf", "png", "dot", "svg"]:
            save_cfg_graph(cfg, output_dir, show_reil, output_format, immediate_format)

        if output_format == "txt":
            save_cfg_text(cfg, output_dir, show_reil, brief)

def _extract_call_targets(self, bbs):
    call_targets = []
    for bb in bbs:
        for instr in bb:
            if self._arch_info.instr_is_call(instr):
                target = helper.extract_call_target(instr)

                if target:
                    call_targets.append(target)

    return call_targets

def _bb_ends_in_direct_jmp(self, bb):
    last_instr = bb.instrs[-1]

    return self._arch_info.instr_is_branch(last_instr) and not self._arch_info.instr_is_branch_cond(last_instr)

def _bb_ends_in_return(self, bb):
    last_instr = bb.instrs[-1]

    return self._arch_info.instr_is_ret(last_instr)

def classify(self, gadget):
    """Classify gadgets.
    """
    typed_gadgets = []

    for g_type, g_classifier in self._classifiers.items():
        try:
            typed_gadgets += self._classify(gadget, g_classifier, g_type, self._emu_iters)
        except:
            import traceback

            print("[-] Error classifying gadgets :")
            print(gadget)
            print("")
            print(traceback.format_exc())

    # Sort and return.
    return sorted(typed_gadgets, key=lambda g: str(g))

def sort_gadgets_by_type(gadgets):
    # Sort gadgets by type.
    gadgets_by_type = {}

    for gadget in gadgets:
        if gadget.type not in gadgets_by_type:
            gadgets_by_type[gadget.type] = []

        gadgets_by_type[gadget.type] += [gadget]

    return gadgets_by_type

def sort_gadgets_by_address(gadgets):
    # Sort gadgets by address.
    gadgets_by_address = {}

    for gadget in gadgets:
        if gadget.address not in gadgets_by_address:
            gadgets_by_address[gadget.address] = []

        gadgets_by_address[gadget.address] += [gadget]

    return gadgets_by_address

def sort_gadgets_by_depth(gadgets):
    # Sort gadgets by depth (instructions number).
    gadgets_by_depth = {}

    for gadget in gadgets:
        instrs_count = len(gadget.instrs)

        if instrs_count not in gadgets_by_depth:
            gadgets_by_depth[instrs_count] = []

        gadgets_by_depth[instrs_count] += [gadget]

    return gadgets_by_depth

def print_gadgets_raw(gadgets, f, sort_mode, color, title, show_binary):
    # Print title
    print(title,            file=f)
    print("=" * len(title), file=f)
    print(" " * len(title), file=f)

    sort_methods = {
        'addr': sort_gadgets_by_address,
        'depth': sort_gadgets_by_depth,
    }

    gadgets_sorted = sort_methods[sort_mode](gadgets)

    for key in sorted(gadgets_sorted.keys()):
        for gadget in gadgets_sorted[key]:
            asm_instrs = [str(instr) for instr in gadget.instrs]

            if color:
                asm_instrs = [highlight(s, NasmLexer(), TerminalFormatter()) for s in asm_instrs]

            asm_instrs_str = " ; ".join(asm_instrs).replace("\n", "")

            if show_binary:
                try:
                    asm_bytes = ["%02x" % ord(b) for instr in gadget.instrs for b in instr.bytes]
                    asm_bytes_str = "".join(asm_bytes)

                    print("0x%08x: %32s | %s" % (gadget.address, asm_bytes_str, asm_instrs_str), file=f)
                except:
                    print("[+] Error!")
                    print("\t0x%08x: %s" % (gadget.address, asm_instrs_str), file=f)
            else:
                print("0x%08x: %s" % (gadget.address, asm_instrs_str), file=f)

        if sort_mode == "depth":
            print("", file=f)

    if sort_mode == "addr":
        print("", file=f)

    # Print summary.
    summary_item_fmt = "[+] {name} : {value}"
    summary_ruler_fmt = "{0}"

    summary_item = summary_item_fmt.format(name=title, value=len(gadgets))
    summary_ruler = summary_ruler_fmt.format(" " * len(summary_item))

    print(summary_item,  file=f)
    print(summary_ruler, file=f)

def do_classify(b, gadgets, args):
    start = time.time()

    classified = []

    for gadget in gadgets:
        classified += b.gadget_classifier.classify(gadget)

    end = time.time()

    classify_time = end - start

    return classified, classify_time

def do_verify(b, classified, args):
    start = time.time()

    verified = []
    invalid = []

    for gadget in classified:
        valid = b.gadget_verifier.verify(gadget)

        if valid:
            gadget.is_valid = True
            verified += [gadget]
        else:
            invalid += [gadget]

    end = time.time()

    verify_time = end - start

    discarded = []

    # Filter by operand size.
    if args.r:
        verified_temp = []

        for gadget in verified:
            if all([op.size == args.r for op in gadget.sources]) and \
                all([op.size == args.r for op in gadget.destination]):
                verified_temp += [gadget]

        verified = verified_temp

    # Filter duplicate gadgets.
    if args.unique:
        verified_by_type = {}

        for gadget in verified:
            if gadget.type not in verified_by_type:
                verified_by_type[gadget.type] = []

            gadgets = verified_by_type[gadget.type]

            if not any(gadget == another for another in gadgets):
                gadgets += [gadget]
            else:
                discarded += [gadget]

        verified_distinct = []

        for _, gadgets in verified_by_type.items():
            verified_distinct += gadgets

        verified = verified_distinct

        end = time.time()

        verify_time = end - start

    return verified, verify_time, discarded, invalid

def _analyze_execution_results(self, results):
    matching_candidates, _ = results[0]

    classified_candidates = []

    for matching_candidate in matching_candidates:
        valid_matching = True

        for matches, _ in results[1:]:
            if matching_candidate not in matches:
                valid_matching = False

        if valid_matching and matching_candidate not in classified_candidates:
            classified_candidates.append(matching_candidate)

    modified_regs = set()

    for _, mod_regs in results:
        modified_regs = modified_regs.union(set(mod_regs))

    return classified_candidates, list(modified_regs)

def _create_typed_gadgets(self, gadget, classified_gadgets, modified_regs, gadget_type):
    typed_gadgets = []

    # Remove register aliases
    mod_regs = []

    for r in modified_regs:
        alias, _ = self._arch_info.alias_mapper.get(r, (None, None))

        if not alias:
            mod_regs += [r]
        elif alias not in modified_regs:
            mod_regs += [r]

    modified_regs_ir = [ReilRegisterOperand(r, self._arch_regs_size[r]) for r in mod_regs]

    for candidate in classified_gadgets:
        typed_gadget = TypedGadget(gadget, gadget_type, gadget.instrs)

        if gadget_type in [GadgetType.Arithmetic, GadgetType.ArithmeticLoad, GadgetType.ArithmeticStore]:
            typed_gadget.operation = candidate["op"]

        if candidate.get("op", "") != "nop":
            typed_gadget.sources = candidate["src"]
            typed_gadget.destination = candidate["dst"]

            if gadget_type == GadgetType.StoreMemory:
                typed_gadget.modified_registers = [r for r in modified_regs_ir]
            else:
                typed_gadget.modified_registers = [r for r in modified_regs_ir if r not in typed_gadget.destination]

        typed_gadgets += [typed_gadget]

    return typed_gadgets

def _init_regs_random(self):
    """Initialize register with random values.
    """
    # Generate random values and make sure they are all different.
    values = set()

    while len(values) != len(self._arch_regs_parent):
        values.add(random.randint(0, 2**self._arch_info.operand_size - 1))

    values = list(values)

    # Assign random values to registers.
    regs = {}

    for idx, reg in enumerate(self._arch_regs_parent):
        regs[reg] = values[idx] & (2**self._arch_regs_size[reg] - 1)

    return regs

def _is_valid_ins(self, ins_ir):
    """Check for instruction validity as a gadgets.
    """
    invalid_instrs = [
        ReilMnemonic.JCC,
        ReilMnemonic.UNDEF,
        ReilMnemonic.UNKN,
    ]

    return not any([i.mnemonic in invalid_instrs for i in ins_ir])

def is_valid(self):
    """Get gadgets validity status.
    """
    if not self._verified:
        raise Exception("Typed Gadget not Verified!")

    return self._is_valid

def dump_load_memory(gadget):
    fmt = "%s <- mem[%s] > {%s}"

    mod_regs = [r for r in gadget.modified_registers]

    src_regs = []
    for src in gadget.sources:
        if isinstance(src, ReilEmptyOperand):
            continue

        if isinstance(src, ReilImmediateOperand) and src.immediate == 0:
            continue

        src_regs += [src]

    fmt_params = (
        str(gadget.destination[0]),
        " + ".join(map(str, src_regs)),
        "; ".join(map(str, mod_regs))
    )

    return fmt % fmt_params

def dump_store_memory(gadget):
    fmt = "mem[%s] <- %s > {%s}"

    mod_regs = [r for r in gadget.modified_registers]

    dst_regs = []
    for dst in gadget.destination:
        if isinstance(dst, ReilEmptyOperand):
            continue

        if isinstance(dst, ReilImmediateOperand) and dst.immediate == 0:
            continue

        dst_regs += [dst]

    fmt_params = (
        " + ".join(map(str, dst_regs)),
        str(gadget.sources[0]),
        "; ".join(map(str, mod_regs))
    )

    return fmt % fmt_params

def dump_arithmetic_store(gadget):
    fmt = "mem[%s] <- mem[%s] %s %s > {%s}"

    mod_regs = [r for r in gadget.modified_registers]

    src_regs = []
    for src in gadget.sources[0:2]:
        if isinstance(src, ReilEmptyOperand):
            continue

        if isinstance(src, ReilImmediateOperand) and src.immediate == 0:
            continue

        src_regs += [src]

    dst_regs = []
    for dst in gadget.destination:
        if isinstance(dst, ReilEmptyOperand):
            continue

        if isinstance(dst, ReilImmediateOperand) and dst.immediate == 0:
            continue

        dst_regs += [dst]

    fmt_params = (
        " + ".join(map(str, dst_regs)),
        " + ".join(map(str, src_regs)),
        gadget.operation,
        str(gadget.sources[2]),
        "; ".join(map(str, mod_regs))
    )

    return fmt % fmt_params

def compare_contexts(context_init, arm_context, reil_context):
    match = True
    mask = 2**32-1

    for reg in sorted(context_init.keys()):
        if (arm_context[reg] & mask) != (reil_context[reg] & mask):
            match = False
            break

    return match

def find(self, start_address, end_address, byte_depth=20, instrs_depth=2):
    """Find gadgets.
    """
    self._max_bytes = byte_depth
    self._instrs_depth = instrs_depth

    if self._architecture == ARCH_X86:
        candidates = self._find_x86_candidates(start_address, end_address)
    elif self._architecture == ARCH_ARM:
        candidates = self._find_arm_candidates(start_address, end_address)
    else:
        raise Exception("Architecture not supported.")

    # Sort and return.
    return sorted(candidates, key=lambda g: g.address)

def _find_x86_candidates(self, start_address, end_address):
    """Finds possible 'RET-ended' gadgets.
    """
    roots = []

    # find gadgets tail
    for addr in xrange(start_address, end_address + 1):
        # TODO: Make this 'speed improvement' architecture-agnostic
        op_codes = [
            0xc3,     # RET
            0xc2,     # RET imm16
            0xeb,     # JMP rel8
            0xe8,     # CALL rel{16,32}
            0xe9,     # JMP rel{16,32}
            0xff,     # JMP/CALL r/m{16,32,64}
        ]

        if self._mem[addr] not in op_codes:
            continue

        try:
            asm_instr = self._disasm.disassemble(
                self._mem[addr:min(addr+16, end_address + 1)],
                addr
            )
        except:
            asm_instr = None

        if not asm_instr:
            continue

        # restarts ir register numbering
        self._ir_trans.reset()

        try:
            ins_ir = self._ir_trans.translate(asm_instr)
        except:
            continue

        # build gadgets
        if ins_ir[-1] and (ins_ir[-1].mnemonic == ReilMnemonic.JCC and isinstance(ins_ir[-1].operands[2], ReilRegisterOperand)):

            # add for REX.W + FF /3 call instruction
            if ins_ir[-1].mnemonic == ReilMnemonic.JCC:
                # try addr - 1
                try:
                    asm_instr_1 = self._disasm.disassemble(
                        self._mem[addr-1:min(addr+15, end_address + 1)],
                        addr
                    )

                    self._ir_trans.reset()

                    ins_ir_1 = self._ir_trans.translate(asm_instr_1)

                    if ins_ir_1[-1].mnemonic == ReilMnemonic.JCC:
                        addr = addr - 1
                        asm_instr = asm_instr_1
                        ins_ir = ins_ir_1
                except:
                        pass

            asm_instr.ir_instrs = ins_ir

            root = GadgetTreeNode(asm_instr)

            roots.append(root)

            self._build_from(addr, root, start_address, self._instrs_depth)

    # filter roots with no children
    roots = [r for r in roots if len(r.get_children()) > 0]

    # build gadgets
    root_gadgets = [self._build_gadgets(r) for r in roots]

    # flatten root gadgets list
    candidates = [item for l in root_gadgets for item in l]

    return candidates

def _build_from(self, address, root, base_address, depth=2):
    """Build gadgets recursively.
    """
    if depth == 0:
        return

    end_addr = address

    for step in range(1, self._max_bytes + 1):
        start_addr = address - step

        if start_addr < 0 or start_addr < base_address:
            break

        raw_bytes = self._mem[start_addr:end_addr]

        # TODO: Improve this code.
        if self._architecture == ARCH_ARM:
            try:
                asm_instr = self._disasm.disassemble(raw_bytes, start_addr, architecture_mode=self._architecture_mode)
            except InvalidDisassemblerData:
                continue
        else:
            try:
                asm_instr = self._disasm.disassemble(raw_bytes, start_addr)
            except:
                asm_instr = None

        if not asm_instr or asm_instr.size != step:
            continue

        try:
            ir_instrs = self._ir_trans.translate(asm_instr)
        except:
            continue

        if self._is_valid_ins(ir_instrs):
            asm_instr.ir_instrs = ir_instrs

            child = GadgetTreeNode(asm_instr)

            root.add_child(child)

            self._build_from(address - step, child, base_address, depth - 1)

def get_operand_expr(self, operand, mode="post"):
    """Return a smt bit vector that represents a register (architectural or
    temporal).
    """
    if isinstance(operand, ReilRegisterOperand):
        if operand.name in self._arch_info.registers_all:
            # Process architectural registers (eax, ebx, etc.)
            expr = self.get_register_expr(operand.name, mode=mode)
        else:
            # Process temporal registers (t0, t1, etc.)
            var_name = self._get_var_name(operand.name, mode)
            expr = self._translator.make_bitvec(operand.size, var_name)
    elif isinstance(operand, ReilImmediateOperand):
        expr = smtsymbol.Constant(operand.size, operand.immediate)
    else:
        raise Exception("Invalid operand: %s" % str(operand))

    return expr

def add_instruction(self, reil_instruction):
    """Add an instruction for analysis.
    """
    for expr in self._translator.translate(reil_instruction):
        self._solver.add(expr)

def __add_trace_to_solver(self, trace):
    for reil_instr, branch_taken in trace:
        if reil_instr.mnemonic == ReilMnemonic.JCC and isinstance(reil_instr.operands[0], ReilRegisterOperand):
            oprnd = reil_instr.operands[0]
            oprnd_expr = self.__code_analyzer.get_operand_expr(oprnd)

            branch_expr = oprnd_expr != 0x0 if branch_taken else oprnd_expr == 0x0

            # logger.debug("    Branch: {:#010x}:{:02x}  {:s} ({}) - {:s}".format(reil_instr.address >> 8, reil_instr.address & 0xff, reil_instr, branch_taken, branch_expr))

            self.__code_analyzer.add_constraint(branch_expr)
        else:
            self.__code_analyzer.add_instruction(reil_instr)

