def get_expr_value(self, expr):
    """Get a value for an expression.
    """
    return self._solver.get_value(expr)

def __process_branch_uncond(self, instr, trace_current, not_taken_addr):
    # TAKEN branch (for example: JCC 0x1, empty, oprnd2).
    if instr.operands[0].immediate != 0x0:
        # Direct branch (for example: JCC 0x1, empty, INTEGER)
        if isinstance(instr.operands[2], ReilImmediateOperand):
            trace_current += [(instr, None)]

            next_ip = self.__cpu.execute(instr)

        # Indirect branch (for example: JCC 0x1, empty, REGISTER)
        else:
            raise Exception("Indirect jump not supported yet.")

    # NOT TAKEN branch (for example: JCC 0x0, empty, oprnd2).
    else:
        next_ip = not_taken_addr

    return next_ip

def __setitem__(self, index, value):
    if index == 0:
        self.__emulator.registers['rdi'] = value
    elif index == 1:
        self.__emulator.registers['rsi'] = value
    elif index == 2:
        self.__emulator.registers['rdx'] = value
    elif index == 3:
        self.__emulator.registers['rcx'] = value
    elif index == 4:
        self.__emulator.registers['r8'] = value
    elif index == 5:
        self.__emulator.registers['r9'] = value
    else:
        raise NotImplementedError()

def __setitem__(self, index, value):
    if index == 0:
        self.__emulator.registers['r0'] = value
    elif index == 1:
        self.__emulator.registers['r1'] = value
    elif index == 2:
        self.__emulator.registers['r2'] = value
    elif index == 3:
        self.__emulator.registers['r3'] = value
    else:
        raise NotImplementedError()

def is_conditional_jump(instruction):
    return instruction.mnemonic == ReilMnemonic.JCC and \
                isinstance(instruction.operands[0], ReilRegisterOperand)

def instr_is_syscall(self, instruction):
    syscall_instrs = [
        "int", "syscall", "sysenter"
    ]

    return instruction.mnemonic in syscall_instrs

def instr_is_branch(self, instruction):
    branch_instr = [
        "bal", "bcs", "beq", "bge", "bgt", "bhs", "ble", "blo",
        "bls", "blt", "bne", "bpl", "bx", "b", "bhi",
    ]

    return instruction.mnemonic_full in branch_instr

def instr_is_branch_cond(self, instruction):
    branch_instr = [
        "bcs", "beq", "bge", "bgt", "bhi", "bhs", "ble", "blo",
        "bls", "blt", "bne", "bpl",
    ]

    return instruction.mnemonic_full in branch_instr

def fetch(self, address):
    base_addr, index = split_address(address)

    if base_addr not in self.__container:
        self.__resolve_address(base_addr)

    return self.__container[base_addr].get(index)

def max_instruction_size(self):
    """Return the maximum instruction size in bytes.
    """
    instruction_size_map = {
        ARCH_X86_MODE_32: 16,
        ARCH_X86_MODE_64: 16,
    }

    return instruction_size_map[self._arch_mode]

def address_size(self):
    address_size_map = {
        ARCH_ARM_MODE_ARM:   32,
        ARCH_ARM_MODE_THUMB: 32,
    }

    return address_size_map[self._arch_mode]

def max_instruction_size(self):
    """Return the maximum instruction size in bytes.
    """
    instruction_size_map = {
        ARCH_ARM_MODE_ARM: 4,

        # NOTE: THUMB instructions are 2 byte long but THUMBv2
        # instruction have both 2 and 4 byte long.
        ARCH_ARM_MODE_THUMB: 4,
    }

    return instruction_size_map[self._arch_mode]

def flags_register(self):
    flag_register_map = {
        ARCH_X86_MODE_32: 'eflags',
        ARCH_X86_MODE_64: 'rflags',
    }

    return flag_register_map[self._arch_mode]

def __get_flag(self, flag):
    flag = flag.lower()

    if flag not in self.__arch.registers_flags:
        raise TranslationError("Invalid flag")

    if flag not in self.__flags:
        self.__flags[flag] = ReilRegisterOperand(flag, self.__arch.registers_size[flag])

    return self.__flags[flag]

def translate(self, instruction):
    """Return REIL representation of an instruction.
    """
    try:
        trans_instrs = self._translate(instruction)
    except Exception:
        self._log_translation_exception(instruction)

        raise TranslationError("Unknown error")

    return trans_instrs

def __resolve_loops(self, address, instrs):
    # Collect labels.
    idx_by_labels = {}
    instrs_no_labels = []
    curr = 0

    for i in instrs:
        if isinstance(i, ReilLabel):
            idx_by_labels[i.name] = curr
        else:
            instrs_no_labels.append(i)
            curr += 1

    instrs[:] = instrs_no_labels

    # Resolve instruction addresses and JCC targets.
    for index, instr in enumerate(instrs):
        instr.address = to_reil_address(address, index)

        if instr.mnemonic == ReilMnemonic.JCC:
            target = instr.operands[2]

            if isinstance(target, ReilLabel):
                addr = to_reil_address(address, idx_by_labels[target.name])
                size = self._arch_info.address_size + 8

                instr.operands[2] = ReilImmediateOperand(addr, size)

    return instrs

def _translate(self, instruction):
    mnemonic = instruction.mnemonic

    # Check whether it refers to the strings instruction or the sse
    # instruction.
    if instruction.mnemonic in ["movsd"]:
        if instruction.bytes[0] not in ["\xa4", "\xa5"]:
            mnemonic += "_sse"

    tb = TranslationBuilder(self._ir_name_generator, self._arch_info)

    if mnemonic in dispatcher:
        dispatcher[mnemonic](self, tb, instruction)
    else:
        tb.add(self._builder.gen_unkn())

        self._log_not_supported_instruction(instruction)

    return tb.instanciate(instruction.address)

def _translate(self, instruction):
    # Retrieve translation function.
    mnemonic = instruction.mnemonic

    tb = TranslationBuilder(self._ir_name_generator, self._arch_info)

    if instruction.condition_code is None:
        instruction.condition_code = ARM_COND_CODE_AL

    # Translate instruction.
    if mnemonic in translators.dispatcher:
        if instruction.mnemonic in ["b", "bl", "bx", "blx", "bne", "beq", "bpl",
                                    "ble", "bcs", "bhs", "blt", "bge", "bhi",
                                    "blo", "bls"]:
            translators.dispatcher[mnemonic](self, tb, instruction)
        else:
            # Pre-processing: evaluate flags
            if instruction.condition_code != ARM_COND_CODE_AL:
                cond_not_met = ReilLabel('cond_not_met')
                cond = ArmConditionCodeHelper.evaluate_cond_code(self._flags, tb, instruction.condition_code)
                neg_cond = negate_reg(tb, cond)
                tb.add(tb._builder.gen_jcc(neg_cond, cond_not_met))
                translators.dispatcher[mnemonic](self, tb, instruction)
                tb.add(cond_not_met)
                tb.add(tb._builder.gen_nop())
            else:
                translators.dispatcher[mnemonic](self, tb, instruction)
    else:
        tb.add(self._builder.gen_unkn())

        self._log_not_supported_instruction(instruction)

    return tb.instanciate(instruction.address)

def disassemble(self, data, address, architecture_mode=None):
    """Disassemble the data into an instruction.
    """
    # TODO: Improve this code!
    if architecture_mode is None:
        if self._arch_mode is None:
            architecture_mode = ARCH_ARM_MODE_THUMB
        else:
            architecture_mode = self._arch_mode

    self._disassembler = self._available_disassemblers[architecture_mode]

    disasm = self._cs_disassemble_one(data, address)

    instr = self._cs_translate_insn(disasm)

    if instr:
        instr.address = address
        instr.size = disasm.size
        instr.bytes = data[0:disasm.size]
    else:
        raise DisassemblerError()

    return instr

def _cs_disassemble_one(self, data, address):
    """Disassemble the data into an instruction in string form.
    """
    disasm = list(self._disassembler.disasm(bytes(data), address))

    # TODO: Improve this check.
    if len(disasm) > 0:
        return disasm[0]
    else:
        cs_arm = Cs(CS_ARCH_ARM, CS_MODE_ARM)
        cs_arm.detail = True
        disasm = list(cs_arm.disasm(bytes(data), address))

        if len(disasm) > 0:
            return disasm[0]
        else:
            raise InvalidDisassemblerData("CAPSTONE: Unknown instruction (Addr: {:s}).".format(hex(address)))

def overflow_from_sub(tb, oprnd0, oprnd1, result):
    op1_sign = extract_bit(tb, oprnd0, oprnd0.size - 1)
    op2_sign = extract_bit(tb, oprnd1, oprnd0.size - 1)
    res_sign = extract_bit(tb, result, oprnd0.size - 1)

    return and_regs(tb, unequal_regs(tb, op1_sign, op2_sign), unequal_regs(tb, op1_sign, res_sign))

def _overflow_from_sub_uf(self, tb, oprnd0, oprnd1, result):
    # Evaluate overflow and update the flag
    tb.add(tb._builder.gen_str(overflow_from_sub(tb, oprnd0, oprnd1, result), self._flags.vf))

def evaluate_a(flags, tb):
    # above (CF=0 and ZF=0)
    return and_regs(tb, negate_reg(tb, flags.cf),
                    negate_reg(tb, flags.zf))

def evaluate_nb(flags, tb):
    # not below (CF=0)
    return negate_reg(tb, flags.cf)

def evaluate_ne(flags, tb):
    # not equal (ZF=0)
    return negate_reg(tb, flags.zf)

def evaluate_nle(flags, tb):
    # not less or equal (ZF=0 and SF=OF)
    return and_regs(tb, negate_reg(tb, flags.zf),
                    equal_regs(tb, flags.sf, flags.of))

def evaluate_no(flags, tb):
    # not overflow (OF=0)
    return negate_reg(tb, flags.of)

def evaluate_ns(flags, tb):
    # not sign (SF=0)
    return negate_reg(tb, flags.sf)

def evaluate_pe(flags, tb):
    # parity even (PF=1)
    return flags.pf

def evaluate_po(flags, tb):
    # parity odd (PF=0)
    return negate_reg(tb, flags.pf)

def evaluate_lt(flags, tb):
    # LT: N != V
    return negate_reg(tb, ArmConditionCodeHelper.evaluate_ge(flags, tb))

def evaluate_gt(flags, tb):
    # GT: (Z == 0) and (N == V)
    return and_regs(tb, negate_reg(tb, flags.zf), ArmConditionCodeHelper.evaluate_ge(flags, tb))

def evaluate_be(flags, tb):
    # below or equal (CF=1 or ZF=1)
    return or_regs(tb, flags.cf, flags.zf)

def evaluate_na(flags, tb):
    # not above (CF=1 or ZF=1).
    return or_regs(tb, flags.cf, flags.zf)

def evaluate_ls(flags, tb):
    # LS: C clear or Z set
    return or_regs(tb, negate_reg(tb, flags.cf), flags.zf)

def evaluate_g(flags, tb):
    # greater (ZF=0 and SF=OF)
    return and_regs(tb, negate_reg(tb, flags.zf),
                    equal_regs(tb, flags.sf, flags.of))

def evaluate_ge(flags, tb):
    # greater or equal (SF=OF)
    return equal_regs(tb, flags.sf, flags.of)

def evaluate_nl(flags, tb):
    # not less (SF=OF)
    return equal_regs(tb, flags.sf, flags.of)

def evaluate_l(flags, tb):
    # less (SF != OF)
    return unequal_regs(tb, flags.sf, flags.of)

def evaluate_le(flags, tb):
    # less or equal (ZF=1 or SF != OF)
    return or_regs(tb, flags.zf,
                   unequal_regs(tb, flags.sf, flags.of))

def evaluate_ng(flags, tb):
    # not greater (ZF=1 or SF != OF)
    return or_regs(tb, flags.zf,
                   unequal_regs(tb, flags.sf, flags.of))

def evaluate_nge(flags, tb):
    # not greater or equal (SF != OF)
    return unequal_regs(tb, flags.sf, flags.of)

def compute_memory_address(self, tb, mem_operand):
    """Return operand memory access translation.
    """
    base = ReilRegisterOperand(mem_operand.base_reg.name, mem_operand.size)

    if mem_operand.displacement:
        address = tb.temporal(mem_operand.size)

        if isinstance(mem_operand.displacement, ArmRegisterOperand):
            disp = ReilRegisterOperand(mem_operand.displacement.name, mem_operand.size)
        elif isinstance(mem_operand.displacement, ArmImmediateOperand):
            disp = ReilImmediateOperand(mem_operand.displacement.immediate, mem_operand.size)
        elif isinstance(mem_operand.displacement, ArmShiftedRegisterOperand):
            disp = self.compute_shifted_register(tb, mem_operand.displacement)
        else:
            raise Exception("compute_memory_address: displacement type unknown")

        if mem_operand.index_type == ARM_MEMORY_INDEX_PRE:
            if mem_operand.disp_minus:
                tb.add(tb._builder.gen_sub(base, disp, address))
            else:
                tb.add(tb._builder.gen_add(base, disp, address))
            tb.add(tb._builder.gen_str(address, base))
        elif mem_operand.index_type == ARM_MEMORY_INDEX_OFFSET:
            if mem_operand.disp_minus:
                tb.add(tb._builder.gen_sub(base, disp, address))
            else:
                tb.add(tb._builder.gen_add(base, disp, address))
        elif mem_operand.index_type == ARM_MEMORY_INDEX_POST:
            tb.add(tb._builder.gen_str(base, address))
            tmp = tb.temporal(base.size)
            if mem_operand.disp_minus:
                tb.add(tb._builder.gen_sub(base, disp, tmp))
            else:
                tb.add(tb._builder.gen_add(base, disp, tmp))
            tb.add(tb._builder.gen_str(tmp, base))
        else:
            raise Exception("compute_memory_address: indexing type unknown")

    else:
        address = base

    return address

def _translate_ldrd(self, tb, instruction):
    if len(instruction.operands) > 2:  # Rd2 has been specified (UAL syntax)
        addr_reg = self._reg_acc_translator.compute_memory_address(tb, instruction.operands[2])
    else:
        addr_reg = self._reg_acc_translator.compute_memory_address(tb, instruction.operands[1])

    reil_operand = ReilRegisterOperand(instruction.operands[0].name, instruction.operands[0].size)

    tb.add(tb._builder.gen_ldm(addr_reg, reil_operand))

    addr_reg = add_to_reg(tb, addr_reg, ReilImmediateOperand(4, reil_operand.size))

    if len(instruction.operands) > 2:  # Rd2 has been specified (UAL syntax)
        reil_operand = ReilRegisterOperand(instruction.operands[1].name, instruction.operands[0].size)
    else:
        # TODO: Assuming the register is written in its number format
        # (no alias like lr or pc).
        reil_operand = ReilRegisterOperand('r' + str(int(reil_operand.name[1:]) + 1), reil_operand.size)

    tb.add(tb._builder.gen_ldm(addr_reg, reil_operand))

def _translate_strd(self, tb, instruction):
    if len(instruction.operands) > 2:  # Rd2 has been specified (UAL syntax)
        addr_reg = self._reg_acc_translator.compute_memory_address(tb, instruction.operands[2])
    else:
        addr_reg = self._reg_acc_translator.compute_memory_address(tb, instruction.operands[1])

    reil_operand = ReilRegisterOperand(instruction.operands[0].name, instruction.operands[0].size)

    tb.add(tb._builder.gen_stm(reil_operand, addr_reg))

    addr_reg = add_to_reg(tb, addr_reg, ReilImmediateOperand(4, reil_operand.size))

    if len(instruction.operands) > 2:  # Rd2 has been specified (UAL syntax)
        reil_operand = ReilRegisterOperand(instruction.operands[1].name, instruction.operands[0].size)
    else:
        # TODO: Assuming the register is written in its number format
        # (no alias like lr or pc).
        reil_operand = ReilRegisterOperand('r' + str(int(reil_operand.name[1:]) + 1), reil_operand.size)

    tb.add(tb._builder.gen_stm(reil_operand, addr_reg))

def _translate_ldm_stm(self, tb, instruction, load=True):
    # LDM and STM have exactly the same logic except one loads and the
    # other stores It is assumed that the disassembler (for example
    # Capstone) writes the register list in increasing order

    base = self._reg_acc_translator.read(tb, instruction.operands[0])
    reg_list = self._reg_acc_translator.read(tb, instruction.operands[1])

    if instruction.ldm_stm_addr_mode is None:
        instruction.ldm_stm_addr_mode = ARM_LDM_STM_IA  # default mode for load and store

    if load:
        load_store_fn = _load_value
        # Convert stack addressing modes to non-stack addressing modes
        if instruction.ldm_stm_addr_mode in ldm_stack_am_to_non_stack_am:
            instruction.ldm_stm_addr_mode = ldm_stack_am_to_non_stack_am[instruction.ldm_stm_addr_mode]
    else:  # Store
        load_store_fn = _store_value
        if instruction.ldm_stm_addr_mode in stm_stack_am_to_non_stack_am:
            instruction.ldm_stm_addr_mode = stm_stack_am_to_non_stack_am[instruction.ldm_stm_addr_mode]

    pointer = tb.temporal(base.size)
    tb.add(self._builder.gen_str(base, pointer))
    reg_list_size_bytes = ReilImmediateOperand(self._ws.immediate * len(reg_list), base.size)

    if instruction.ldm_stm_addr_mode == ARM_LDM_STM_IA:
        for reg in reg_list:
            load_store_fn(self, tb, pointer, reg)
            pointer = add_to_reg(tb, pointer, self._ws)
    elif instruction.ldm_stm_addr_mode == ARM_LDM_STM_IB:
        for reg in reg_list:
            pointer = add_to_reg(tb, pointer, self._ws)
            load_store_fn(self, tb, pointer, reg)
    elif instruction.ldm_stm_addr_mode == ARM_LDM_STM_DA:
        reg_list.reverse()  # Assuming the registry list was in increasing registry number
        for reg in reg_list:
            load_store_fn(self, tb, pointer, reg)
            pointer = sub_to_reg(tb, pointer, self._ws)
    elif instruction.ldm_stm_addr_mode == ARM_LDM_STM_DB:
        reg_list.reverse()
        for reg in reg_list:
            pointer = sub_to_reg(tb, pointer, self._ws)
            load_store_fn(self, tb, pointer, reg)
    else:
        raise Exception("Unknown addressing mode.")

    # Write-back
    if instruction.operands[0].wb:
        if instruction.ldm_stm_addr_mode == ARM_LDM_STM_IA or instruction.ldm_stm_addr_mode == ARM_LDM_STM_IB:
            tmp = add_to_reg(tb, base, reg_list_size_bytes)
        elif instruction.ldm_stm_addr_mode == ARM_LDM_STM_DA or instruction.ldm_stm_addr_mode == ARM_LDM_STM_DB:
            tmp = sub_to_reg(tb, base, reg_list_size_bytes)
        tb.add(self._builder.gen_str(tmp, base))

def compute_shifted_register(self, tb, sh_op):
    base = ReilRegisterOperand(sh_op.base_reg.name, sh_op.size)

    if sh_op.shift_amount:
        ret = tb.temporal(sh_op.size)

        if isinstance(sh_op.shift_amount, ArmImmediateOperand):
            sh_am = ReilImmediateOperand(sh_op.shift_amount.immediate, sh_op.size)
        elif isinstance(sh_op.shift_amount, ArmRegisterOperand):
            sh_am = ReilRegisterOperand(sh_op.shift_amount.name, sh_op.shift_amount.size)
        else:
            raise NotImplementedError("Instruction Not Implemented: Unknown shift amount type.")

        if sh_op.shift_type == 'lsl':
            if isinstance(sh_am, ReilImmediateOperand):
                tb.add(tb._builder.gen_bsh(base, sh_am, ret))
            else:
                sh_am_greater_32_label = tb.label('sh_am_greater_32_label')
                sh_am_end_label = tb.label('sh_am_end_label')

                sh_am_7_0 = and_regs(tb, sh_am, tb.immediate(0xFF, sh_am.size))

                tb.add(tb._builder.gen_jcc(greater_than_or_equal(tb, sh_am_7_0, tb.immediate(33, sh_am_7_0.size)), sh_am_greater_32_label))

                # Shift < 32 => shifted_register = base lsl sh_am
                tb.add(tb._builder.gen_bsh(base, sh_am_7_0, ret))
                jump_to(tb, sh_am_end_label)

                # Shift >= 32 => shifted_register = 0
                tb.add(sh_am_greater_32_label)
                tb.add(tb._builder.gen_str(tb.immediate(0x0, ret.size), ret))

                tb.add(sh_am_end_label)
        else:
            # TODO: Implement other shift types
            raise NotImplementedError("Instruction Not Implemented: Shift type.")
    else:
        ret = base

    return ret

