def __str__(self):
    sep = ""

    string = ""

    if self._modifier:
        string = self._modifier + " "

    if self._segment:
        string += self._segment + ":"

    string += "["

    if self._base:
        string += self._base

    if self._index:
        if self._base:
            string += sep + "+" + sep

        string += self._index
        string += sep + "*" + sep + str(self._scale)

    if self._displacement != 0:
        imm_hex = hex(self._displacement)

        if self._base or self._index:
            if imm_hex[0] == "-":
                string += sep + sep
            else:
                string += sep + "+" + sep

        string += imm_hex[:-1] if imm_hex[-1] == 'L' else imm_hex

    string += "]"

    return string

