    string = "{"
    for i in range(len(self._reg_list)):
        if i > 0:
            string += ", "
        reg_range = self._reg_list[i]
        string += str(reg_range[0])
        if len(reg_range) > 1:
            string += " - " + str(reg_range[1])
    string += "}"

