    tb.add(tb._builder.gen_str(imm, flag))

def __init__(self, architecture_mode):
    super(X86Disassembler, self).__init__()

    arch_mode_map = {
        ARCH_X86_MODE_32: CS_MODE_32,
        ARCH_X86_MODE_64: CS_MODE_64
    }

    self._arch_mode = architecture_mode
    self._arch_info = X86ArchitectureInformation(architecture_mode)

    self._parser = X86Parser(architecture_mode)
    self._disassembler = Cs(CS_ARCH_X86, arch_mode_map[architecture_mode])

def __setup_available_disassemblers(self):
    arch_map = {
        ARCH_ARM_MODE_ARM:   CS_MODE_ARM,
        ARCH_ARM_MODE_THUMB: CS_MODE_THUMB,
    }

    self._available_disassemblers = {
        ARCH_ARM_MODE_ARM:   Cs(CS_ARCH_ARM, arch_map[ARCH_ARM_MODE_ARM]),
        ARCH_ARM_MODE_THUMB: Cs(CS_ARCH_ARM, arch_map[ARCH_ARM_MODE_THUMB]),
    }

    self._available_disassemblers[ARCH_ARM_MODE_ARM].detail = True
    self._available_disassemblers[ARCH_ARM_MODE_THUMB].detail = True

def compare_contexts(context_init, x86_context, reil_context):
    match = True
    mask = 2**64-1

    for reg in sorted(context_init.keys()):
        if (x86_context[reg] & mask) != (reil_context[reg] & mask):
            match = False
            break

    return match

def format_asm_instruction(asm_instr, options):
    nasm_lexer = NasmLexer()
    term_formatter = TerminalFormatter()

    if options.color:
        asm_str = highlight(str(asm_instr), nasm_lexer, term_formatter)[:-1]
    else:
        asm_str = str(asm_instr)

    return asm_str

def _translate_movabs(self, tb, instruction):
