    oprnd = X86RegisterOperand('ecx', 32)

    return oprnd

def evaluate_cc(flags, tb, condition_code):
    eval_cond_fn_name = 'evaluate_' + condition_code
    eval_cond_fn = getattr(X86ConditionCodeHelper, eval_cond_fn_name, None)

    if not eval_cond_fn:
        raise NotImplementedError('Invalid condition code')

    return eval_cond_fn(flags, tb)

def evaluate_e(flags, tb):
    # equal (ZF=1)
    return flags.zf

def evaluate_eq(flags, tb):
    # EQ: Z set
    return flags.zf

def evaluate_ne(flags, tb):
    # NE: Z clear
    return negate_reg(tb, flags.zf)

def evaluate_pl(flags, tb):
    # PL: N clear
    return negate_reg(tb, flags.nf)

def evaluate_hi(flags, tb):
    # HI: C set and Z clear
    return and_regs(tb, flags.cf, negate_reg(tb, flags.zf))

def evaluate_ge(flags, tb):
    # GE: N == V
    return equal_regs(tb, flags.nf, flags.vf)

def evaluate_le(flags, tb):
    # LE: (Z == 1) or (N != V)
    return or_regs(tb, flags.zf, ArmConditionCodeHelper.evaluate_lt(flags, tb))

def evaluate_ae(flags, tb):
    # above or equal (CF=0)
    return negate_reg(tb, flags.cf)

def evaluate_b(flags, tb):
    # below (CF=1)
    return flags.cf

def evaluate_c(flags, tb):
    # carry (CF=1)
    return flags.cf

def evaluate_nae(flags, tb):
    # not above or equal (CF=1)
    return flags.cf

def evaluate_nbe(flags, tb):
    # not below or equal (CF=0 and ZF=0)
    return and_regs(tb, negate_reg(tb, flags.cf),
                    negate_reg(tb, flags.zf))

def evaluate_nc(flags, tb):
    # not carry (CF=0)
    return negate_reg(tb, flags.cf)

def evaluate_o(flags, tb):
    # overflow (OF=1)
    return flags.of

def evaluate_p(flags, tb):
    # parity (PF=1)
    return flags.pf

def evaluate_s(flags, tb):
    # sign (SF=1)
    return flags.sf

def evaluate_z(flags, tb):
    # zero (ZF=1)
    return flags.zf

def evaluate_cs(flags, tb):
    # CS: C set
    return flags.cf

def evaluate_cc(flags, tb):
    # CC: C clear
    return negate_reg(tb, flags.cf)

def evaluate_mi(flags, tb):
    # MI: N set
    return flags.nf

def evaluate_vs(flags, tb):
    # VS: V set
    return flags.vf

def evaluate_vc(flags, tb):
    # VC: V clear
    return negate_reg(tb, flags.vf)

