def print_flags(flags_reg):
    # flags
    flags = {
         31: "nf",  # bit 31
         30: "zf",  # bit 30
         29: "cf",  # bit 29
         28: "vf",  # bit 28
    }

    out = ""

    for bit, flag in flags.items():
        flag_str = flag.upper() if flags_reg & 2**bit else flag.lower()
        out += flag_str + " "

    return out[:-1]

def _translate_str(self, tb, instruction):
    oprnd0 = self._reg_acc_translator.read(tb, instruction.operands[0])

    self._reg_acc_translator.write(tb, instruction.operands[1], oprnd0)

def _translate_rsb(self, tb, instruction):
    instruction.operands[1], instruction.operands[2] = instruction.operands[2], instruction.operands[1]

    _translate_sub(self, tb, instruction)
